151:     pub fn unavailable(&self, revision: NetworkPolicyRevision) {
152:         let mut state = lock_state(&self.state);
153:         if state.revision != revision.0 {
154:             return;
155:         }
156:         if state.policy.take().is_some() {
157:             state.changes.send_replace(());
158:         }
