168:     /// Publishes a successful load only if its account/configuration generation is still current.
169:     pub fn publish(&self, revision: NetworkPolicyRevision, policy: DestinationPolicy) -> bool {
170:         let mut state = lock_state(&self.state);
171:         if state.revision != revision.0 {
172:             return false;
173:         }
174:         state.permits.retain(|permit| {
175:             let Some(permit) = permit.upgrade() else {
176:                 return false;
177:             };
178:             if !permit.destination.allowed_by(&policy) {
179:                 permit.revoked.send_replace(/*value*/ true);
180:             }
181:             true
182:         });
183:         if state.policy.as_ref() != Some(&policy) {
184:             state.policy = Some(policy);
185:             state.changes.send_replace(());
186:         }
187:         true

237:     /// Revokes outstanding operations before an account change or a failed requirements load.
238:     /// This read-side operation can only remove access; publication stays with the controller.
239:     pub fn invalidate(&self) {
240:         if let Some(state) = &self.state {
241:             let mut state = lock_state(state);
242:             state.revision += 1;
243:             state.account += 1;
244:             state.policy = None;
